def house_bowling(rolls: list[int]) -> int:
    score = 0
    idx = 0
    for _ in range(9):
        if rolls[idx] == 10:
            score += 10 + sum(rolls[idx + 1:idx + 3])
            idx += 1
        elif rolls[idx] + rolls[idx + 1] == 10:
            score += 10 + sum(rolls[idx + 2:idx + 3])
            idx += 2
        else:
            score += rolls[idx] + rolls[idx + 1]
            idx += 2
    score += sum(rolls[idx:])
    return score
